// 04 — Workflows (15.5 → 21)
scene({
  start: 15.5, dur: 5.5, theme: 'light', caption: '04 / Workflows', corner: true,
  build(root) {
    const node = (x, ic, title, sub, d, hl) => `
      <div class="abs card" data-node data-d="${d}" style="left:${x}px;top:600px;width:320px;height:190px;box-sizing:border-box;padding:28px;${hl ? `border:2px solid ${ACC}` : ''}">
