      <div class="abs" data-sub style="left:160px;top:476px;width:820px;font-size:36px;line-height:1.4;color:var(--muted)">Triggers, delays and branches in one visual editor. Unlimited on every plan.</div>
      <div class="abs" data-cn style="left:480px;top:693px;width:100px;height:4px;background:#d3cbc1;transform-origin:0 50%"></div>
      <div class="abs" data-cn style="left:900px;top:693px;width:100px;height:4px;background:#d3cbc1;transform-origin:0 50%"></div>
      <div class="abs" data-cn style="left:1320px;top:693px;width:100px;height:4px;background:#d3cbc1;transform-origin:0 50%"></div>
