function tokenize(line) {
  const out = [];
  const re = /("[^"]*")|\b(const|await|new|true)\b|([A-Za-z_]\w*)(?=\s*:)|([A-Za-z_]\w*)|(\s+)|(.)/g;
  let m;
  while ((m = re.exec(line))) {
    const cls = m[1] ? 'str' : m[2] ? 'kw' : m[3] ? 'prop' : m[4] ? 'id' : m[5] ? 'sp' : 'pu';
    out.push([m[0], cls]);
  }
  return out;
}
