  build(root) {
    root.innerHTML = `
      <div class="abs" data-glow style="left:360px;top:40px;width:1200px;height:1000px;background:radial-gradient(circle at 50% 45%, rgba(255,51,0,.20), rgba(255,51,0,0) 62%)"></div>
