    const lock = $(root, '[data-lock]');
    const wm = $(root, '[data-wm]');
    const wmW = wm.getBoundingClientRect().width;
    const lw = 230 + 36 + wmW;
    lock.style.left = ((1920 - lw) / 2) + 'px';
