        s.style.transform = `translate(-50%,-50%) scale(${Math.max(0, p)}) rotate(${lt * 40 + i * 90}deg)`;
      });
      const sIn = E.out3(seg(lt, 2.4, 3.2));
      const ex = E.inOut3(seg(lt, 4.25, 4.85));
