      <path data-sw d="M0 16 Q ${w * 0.5} 44 ${w} 10" pathLength="100" fill="none" stroke="${ACC}" stroke-width="9" stroke-linecap="round" stroke-dasharray="100" stroke-dashoffset="100"/></svg>`;
