      ripple.style.opacity = rp > 0 && rp < 1 ? (1 - rp) * 0.8 : 0;
      ripple.style.transform = `scale(${lerp(1, 1.25, E.out3(rp))})`;
      free.style.opacity = E.out3(seg(lt, 3.0, 3.7));
      url.style.opacity = E.out3(seg(lt, 3.4, 4.0));
    };
  },
