    lline.style.strokeDashoffset = 100 - 100 * E.inOut3(seg(lt, pop + 0.35, pop + 1.25));
    lfill.style.opacity = E.out3(seg(lt, pop + 1.0, pop + 1.5));
    letters.forEach((c, i) => {
      const p = sp(lt, pop + 1.9 + i * 0.065, 320, 26);
