      envs.forEach(e => {
        const k = e.dataset.lane, i = +e.dataset.i, L = LANE[k];
        const tr = trails[envs.indexOf(e)];
        const s = L.start + i * L.gap;
        const p = seg(lt, s, s + L.dur);
        const x = lerp(X0, X1, E.inOut2(p));
        const vis = p > 0 && p < 1 ? 1 : 0;
