  const ratio = r.w / r.h;
  const inside = r.x >= -0.5 && r.y >= -0.5 && r.x + r.w <= vw + 0.5 && r.y + r.h <= vh + 0.5;
  const touchesEdge = Math.abs(r.w - vw) < 1.5 || Math.abs(r.h - vh) < 1.5;
  const fillsMax = Math.abs(r.w - Math.min(vw, vh * 16 / 9)) < 1.5;
